/* 數學概念卡（單元學習用的「教材層」）
   key = <科目>|<冊>|<單元名>，單元名要與 js/data/math.js 的 lesson 欄位一字不差。
   一張卡 = 一個概念 + 一個互動元件 + 一題立即檢核（不計分，答錯就地解釋）。
   check.why[i] = 選到第 i 個選項時要說的話（正解那格放 null，會用預設的鼓勵語）。
   ⚠️ 這是「沒學過的人也看得懂」為目標，不是題目的解析；請用生活情境開場，不要一上來就給定義。
   目前只有原型（三上第8單元），寫法與驗收標準見 docs/bank-maintain-sop.md。 */
