          null,
          '除反了。比值是「前項 ÷ 後項」，這題是 6 ÷ 4。',
          '24 是 6 × 4。比值要用除的，不是乘的。',
          '2 是 6 − 4。比不是在講相差多少，是在講「幾倍」。'
