      body: 'x² ＋ 4 ＝ 0 → x² ＝ −4：實數平方後不會是負的 → 沒有實數解。\n' +
            '從圖形看：y ＝ x² ＋ 4 的頂點在 (0, 4)，整條曲線都在 x 軸上方，當然不會有交點。\n' +
            '（到高二會學虛數 i，那時候這個方程式就有解了。）',
